import io

def rd(p): return io.open(p, encoding='utf8', newline='').read()
def wr(p, s): io.open(p, 'w', encoding='utf8', newline='').write(s)
def sub(p, old, new):
    s = rd(p)
    assert s.count(old) == 1, (p, old[:50], s.count(old))
    wr(p, s.replace(old, new, 1))

